package com.campusradar.growth;

import com.campusradar.common.*;
import com.campusradar.security.CurrentUser;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.time.*;
import java.util.*;
import static com.campusradar.growth.PersonalStore.map;

@RestController
@RequestMapping("/api/v1")
public class GrowthController {
    private final PersonalStore store;private final CurrentUser auth;
    public GrowthController(PersonalStore store,CurrentUser auth){this.store=store;this.auth=auth;}
    @GetMapping("/planner/tasks") public ResponseEntity<?> tasks(HttpServletRequest r,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){String u=auth.requireId(r);return ApiSupport.page(store.all("plan_tasks",u,page,size),page,size,store.count("plan_tasks",u));}
    @PostMapping("/planner/tasks") public ResponseEntity<?> task(HttpServletRequest r,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){PersonalContract.validate("PlanTaskInput",b);String u=auth.requireId(r);return ApiSupport.response(store.write(u,key,"/planner/tasks",b,201,()->store.insert("plan_tasks",u,b)),201);}
    @PatchMapping("/planner/tasks/{id}") public ResponseEntity<?> taskPatch(HttpServletRequest r,@PathVariable String id,@RequestBody Map<String,Object>b){PersonalContract.validate("PlanTaskPatch",b);String u=auth.requireId(r);return ApiSupport.response(store.write(u,null,"",b,200,()->store.patch("plan_tasks",u,id,b)),200);}
    @DeleteMapping("/planner/tasks/{id}")public ResponseEntity<?> taskDelete(HttpServletRequest r,@PathVariable String id,@RequestParam int version){String u=auth.requireId(r);store.write(u,null,"",Map.of("version",version),204,()->{store.delete("plan_tasks",u,id,version);return null;});return ApiSupport.response(null,204);}
    @PostMapping("/planner/generate") public ResponseEntity<?> generate(HttpServletRequest r,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){PersonalContract.validate("GeneratePlan",b);String u=auth.requireId(r);return ApiSupport.response(store.write(u,key,"/planner/generate",b,200,()->generate(u,b)),200);}
    private List<Map<String,Object>> generate(String u,Map<String,Object>b){var result=new ArrayList<Map<String,Object>>();String date=b.get("targetDate").toString();int order=0;for(Object role:(List<?>)b.get("roles")){for(String item:List.of("完善简历","基础知识复习","模拟面试")){String generation=role+":"+item+":"+date;var p=map("u",u,"generation",generation);var rows=store.query("SELECT * FROM plan_tasks WHERE user_id=:u AND generation_key=:generation",p);if(!rows.isEmpty()){result.add(rows.getFirst());continue;}var row=map("title",role+" · "+item,"status","TODO","dueAt",LocalDate.parse(date).atTime(18,0).atOffset(ZoneOffset.UTC).toString(),"notes","每周可投入 "+b.get("hoursPerWeek")+" 小时；按目标日期分配复习。","milestone",role.toString(),"sortOrder",order++,"generationKey",generation);result.add(store.insert("plan_tasks",u,row));}}return result;}
    @GetMapping("/offers")public ResponseEntity<?> offers(HttpServletRequest r,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){String u=auth.requireId(r);return ApiSupport.page(store.all("offers",u,page,size),page,size,store.count("offers",u));}
    private void offerCheck(String u,Map<String,Object>b){if(b.get("applicationId")!=null)store.one("applications",u,b.get("applicationId").toString());uniqueDimensions((List<?>)b.get("scores"),"score");}
    @PostMapping("/offers")public ResponseEntity<?> offerCreate(HttpServletRequest r,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){PersonalContract.validate("OfferInput",b);String u=auth.requireId(r);return ApiSupport.response(store.write(u,key,"/offers",b,201,()->{offerCheck(u,b);return store.insert("offers",u,b);}),201);}
    @PatchMapping("/offers/{id}")public ResponseEntity<?> offerPatch(HttpServletRequest r,@PathVariable String id,@RequestBody Map<String,Object>b){PersonalContract.validate("OfferPatch",b);String u=auth.requireId(r);return ApiSupport.response(store.write(u,null,"",b,200,()->{var full=new LinkedHashMap<>(store.one("offers",u,id));full.putAll(b);offerCheck(u,full);return store.patch("offers",u,id,b);}),200);}
    @DeleteMapping("/offers/{id}")public ResponseEntity<?> offerDelete(HttpServletRequest r,@PathVariable String id,@RequestParam int version){String u=auth.requireId(r);store.write(u,null,"",Map.of("version",version),204,()->{var rows=store.query("SELECT * FROM offer_comparisons WHERE user_id=:u",map("u",u));if(!rows.isEmpty()){var row=rows.getFirst();var ids=new ArrayList<>((List<?>)row.get("offerIds"));if(ids.remove(id))store.patch("offer_comparisons",u,row.get("id").toString(),map("version",row.get("version"),"offerIds",ids));}store.delete("offers",u,id,version);return null;});return ApiSupport.response(null,204);}
    private void uniqueDimensions(List<?> values,String type){Set<Object> seen=new HashSet<>();for(Object v:values){Map<?,?> m=(Map<?,?>)v;Object dim=m.get("dimension");if(dim==null||dim.toString().isBlank()||!seen.add(dim))throw new ApiProblem(422,"VALIDATION_ERROR","评分维度不能重复或为空。");}}
    @GetMapping("/offer-comparison")public ResponseEntity<?> comparison(HttpServletRequest r){return ApiSupport.response(comparison(auth.requireId(r)),200);}
    @SuppressWarnings("unchecked") private Map<String,Object> comparison(String u){var rows=store.query("SELECT * FROM offer_comparisons WHERE user_id=:u",map("u",u));if(rows.isEmpty())return map("version",0,"offerIds",List.of(),"weights",List.of(),"results",List.of());var row=rows.getFirst();var weights=(List<Map<String,Object>>)row.get("weights");var results=new ArrayList<Map<String,Object>>();for(Object id:(List<?>)row.get("offerIds")){var offer=store.one("offers",u,id.toString());var result=PersonalRules.score(weights,(List<Map<String,Object>>)offer.get("scores"));result.put("offerId",id);result.put("annualCashMinor",PersonalRules.annual((Number)offer.get("baseMonthlyMinor"),(Number)offer.get("salaryMonths"),(Number)offer.get("bonusMinor")));results.add(result);}return map("version",row.get("version"),"offerIds",row.get("offerIds"),"weights",weights,"results",results);}
    @PutMapping("/offer-comparison")public ResponseEntity<?> comparisonPut(HttpServletRequest r,@RequestBody Map<String,Object>b){PersonalContract.validate("ComparisonPut",b);String u=auth.requireId(r);return ApiSupport.response(store.write(u,null,"",b,200,()->{for(Object id:(List<?>)b.get("offerIds"))store.one("offers",u,id.toString());uniqueDimensions((List<?>)b.get("weights"),"weight");double sum=((List<?>)b.get("weights")).stream().mapToDouble(o->((Number)((Map<?,?>)o).get("weight")).doubleValue()).sum();if(sum<=0)throw new ApiProblem(422,"VALIDATION_ERROR","至少一项比较权重须大于0。");var rows=store.query("SELECT * FROM offer_comparisons WHERE user_id=:u",map("u",u));if(rows.isEmpty()){if(((Number)b.get("version")).intValue()!=0)throw new ApiProblem(409,"VERSION_CONFLICT","请刷新比较配置。");store.insert("offer_comparisons",u,map("offerIds",b.get("offerIds"),"weights",b.get("weights")));}else store.patch("offer_comparisons",u,rows.getFirst().get("id").toString(),b);return comparison(u);}),200);}
    @PostMapping("/salary/reports")public ResponseEntity<?> salaryReport(HttpServletRequest r,@RequestHeader("Idempotency-Key")String key,@RequestBody Map<String,Object>b){PersonalContract.validate("SalaryInput",b);String u=auth.requireId(r);return ApiSupport.response(store.write(u,key,"/salary/reports",b,201,()->{if(store.db.queryForObject("SELECT COUNT(*) FROM companies WHERE id=:id",map("id",b.get("companyId")),Long.class)==0)throw PersonalStore.missing();var value=new LinkedHashMap<>(b);value.put("verification","SELF_REPORTED");value.put("status","PENDING");return store.insert("salary_reports",u,value);}),201);}
    @GetMapping("/salary/summary")public ResponseEntity<?> salary(@RequestParam(required=false)String companyId,@RequestParam(required=false)String role,@RequestParam(required=false)String city,@RequestParam(required=false)Integer year){if((role!=null&&role.length()>40)||(city!=null&&city.length()>64)||(year!=null&&(year<2000||year>2100)))throw new ApiProblem(422,"VALIDATION_ERROR","薪资筛选无效。");var where=new StringBuilder(" WHERE status='PUBLISHED'");var p=new LinkedHashMap<String,Object>();for(var e:map("companyId",companyId,"role",role,"city",city,"year",year).entrySet())if(e.getValue()!=null){where.append(" AND ").append(PersonalStore.snake(e.getKey())).append("=:").append(e.getKey());p.put(e.getKey(),e.getValue());}var rows=store.query("SELECT base_monthly_minor,salary_months,bonus_minor FROM salary_reports"+where,p);var values=new ArrayList<Long>();for(var row:rows){var cash=PersonalRules.annual((Number)row.get("baseMonthlyMinor"),(Number)row.get("salaryMonths"),(Number)row.get("bonusMinor"));if(cash!=null)values.add(cash);}Collections.sort(values);boolean suppressed=values.size()<5;return ApiSupport.response(map("sampleSize",values.size(),"medianAnnualMinor",suppressed?null:percentile(values,0.5),"p25AnnualMinor",suppressed?null:percentile(values,0.25),"p75AnnualMinor",suppressed?null:percentile(values,0.75),"sampleWindow",year==null?"全部已发布年份":year.toString(),"suppressed",suppressed),200);}
    private long percentile(List<Long> values,double p){return values.get((int)Math.floor((values.size()-1)*p));}
    @GetMapping("/analytics")public ResponseEntity<?> analytics(HttpServletRequest r,@RequestParam String from,@RequestParam String to){var dates=PersonalStore.dates(from,to);String u=auth.requireId(r);var p=map("u",u,"from",dates[0].atStartOfDay(),"to",dates[1].plusDays(1).atStartOfDay());var apps=store.query("SELECT * FROM applications WHERE user_id=:u AND created_at>=:from AND created_at<:to",p);var events=store.query("SELECT application_id,to_stage,occurred_at,undone FROM application_stage_events WHERE user_id=:u AND occurred_at>=:from AND occurred_at<:to AND undone=0",p);Set<String> applied=new HashSet<>(),interviews=new HashSet<>(),offers=new HashSet<>();var daily=new TreeMap<String,Integer>();for(var ev:events){String id=ev.get("applicationId").toString(),stage=ev.get("toStage").toString();if(stage.equals("APPLIED")){if(applied.add(id))daily.merge(ev.get("occurredAt").toString().substring(0,10),1,Integer::sum);}if(Set.of("INTERVIEW_1","INTERVIEW_2","HR").contains(stage))interviews.add(id);if(stage.equals("OFFER"))offers.add(id);}var counts=new LinkedHashMap<String,Integer>();for(String stage:List.of("PENDING","APPLIED","ASSESSMENT","INTERVIEW_1","INTERVIEW_2","HR","OFFER","CLOSED"))counts.put(stage,0);var resumes=new LinkedHashMap<Object,Map<String,Object>>();for(var app:apps){counts.merge(app.get("stage").toString(),1,Integer::sum);Object resume=app.get("resumeId");var row=resumes.computeIfAbsent(resume,k->map("resumeId",k,"applications",0,"interviews",0,"offers",0));row.put("applications",((Number)row.get("applications")).intValue()+1);if(interviews.contains(app.get("id")))row.put("interviews",((Number)row.get("interviews")).intValue()+1);if(offers.contains(app.get("id")))row.put("offers",((Number)row.get("offers")).intValue()+1);}return ApiSupport.response(map("from",from,"to",to,"totalApplications",apps.size(),"appliedCount",applied.size(),"interviewCount",interviews.size(),"offerCount",offers.size(),"interviewRate",applied.isEmpty()?null:Math.min(1d,(double)interviews.size()/applied.size()),"offerRate",applied.isEmpty()?null:Math.min(1d,(double)offers.size()/applied.size()),"stageCounts",counts.entrySet().stream().map(e->map("stage",e.getKey(),"count",e.getValue())).toList(),"dailyApplied",daily.entrySet().stream().map(e->map("date",e.getKey(),"count",e.getValue())).toList(),"resumeEffect",resumes.values().stream().limit(100).toList()),200);}
}
